行内代码代码块语法高亮代码行数高亮部分代码 <p>反引号<code>包围</code>的部分</p> <pre><code>code
</code></pre> <pre><code>require 'redcarpet'
markdown = Redcarpet.new("Hello World!")
puts markdown.to_html
</code></pre> <p>如果你想要你的代码块显示代码行数，只要添加 line-numbers class 就可以了。 例如： <pre><code>function add(x, y) {
return x + y
}
</code></pre></p> <p>你可以通过添加 highlight 属性的方式来高亮代码行数： <pre><code>let todos = [];
function addTodo(task) {
    if (task.trim() === '') {
        console.log('任务内容不能为空');
        return false;
    }
    const newTodo = {
        id: todos.length + 1,
        task: task,
        completed: false,
        createdAt: new Date().toLocaleString()
    };
    todos.push(newTodo);
    console.log(`任务已添加: ${task}`);
    return true;
}
function completeTodo(id) {
    const todo = todos.find(item =&gt; item.id === id);
    if (todo) {
        todo.completed = true;
        console.log(`任务已完成: ${todo.task}`);
    } else {
        console.log(`未找到ID为 ${id} 的任务`);
    }
}
function listTodos() {
    if (todos.length === 0) {
        console.log('暂无任务');
        return;
    }
    console.log('=== 待办列表 ===');
    todos.forEach(todo =&gt; {
        const status = todo.completed ? '✓' : '○';
        console.log(`[${status}] ${todo.id}: ${todo.task}`);
    });
}
addTodo('学习JavaScript');
addTodo('写代码示例');
listTodos();
completeTodo(1);
listTodos();
console.log(`总任务数: ${todos.length}`);
</code></pre></p>
